{
  "title": "Tính thể tích và diện tích xung quanh hình trụ",
  "description": "Bài toán này minh họa cách dựng hình trụ từ tâm hai đáy và một điểm trên vành đáy, sau đó tính thể tích và diện tích xung quanh của nó.",
  "memory_declarations": [
    {
      "name": "O",
      "type": "point3",
      "initial_value": [0, 0, 0],
      "source_fact_id": "o_coords",
      "label": "Tâm đáy dưới"
    },
    {
      "name": "K",
      "type": "point3",
      "initial_value": [0, 0, 10],
      "source_fact_id": "k_coords",
      "label": "Tâm đáy trên"
    },
    {
      "name": "A",
      "type": "point3",
      "initial_value": [6, 0, 0],
      "source_fact_id": "a_coords",
      "label": "Điểm trên đường tròn đáy tâm O"
    },
    {
      "name": "khối trụ",
      "type": "curved_solid",
      "label": "Khối trụ"
    },
    {
      "name": "V",
      "type": "float",
      "label": "Thể tích khối trụ"
    },
    {
      "name": "hình trụ",
      "type": "curved_solid",
      "label": "Hình trụ"
    },
    {
      "name": "Sxq",
      "type": "float",
      "label": "Diện tích xung quanh hình trụ"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "O",
      "at": [0, 0, 0],
      "source_fact_id": "o_coords"
    },
    {
      "kind": "declare_point",
      "target_var": "K",
      "at": [0, 0, 10],
      "source_fact_id": "k_coords"
    },
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [6, 0, 0],
      "source_fact_id": "a_coords"
    },
    {
      "kind": "construct_curved_solid",
      "target_var": "khối trụ",
      "curved_kind": "cylinder",
      "anchor": "O",
      "apex_or_top": "K",
      "rim_point": "A",
      "label": "Hình trụ được tạo bởi tâm đáy dưới O, tâm đáy trên K và điểm A trên vành đáy"
    },
    {
      "kind": "assign",
      "target_var": "hình trụ",
      "expr": {
        "kind": "var",
        "name": "khối trụ"
      }
    },
    {
      "kind": "assign",
      "target_var": "V",
      "expr": {
        "kind": "measure",
        "quantity": "volume",
        "of": "khối trụ"
      }
    },
    {
      "kind": "assign",
      "target_var": "Sxq",
      "expr": {
        "kind": "measure",
        "quantity": "lateral_area",
        "of": "hình trụ"
      }
    }
  ],
  "pedagogical_intent": "Chương trình này minh họa cách định nghĩa và tính toán các thuộc tính cơ bản của hình trụ trong không gian Oxyz, sử dụng các điểm đã cho để xác định hình dạng và kích thước."
}
